<?php
namespace App\Support;
use App\Models\{User,Apprentice,TutorGroup,TimetableGroupBrief as Brief,TimetableFlexibleDay as Day,TimetableStaffWindow as Window};
use Illuminate\Support\Facades\{DB,Crypt};
use Carbon\Carbon;
class TimetableDuties {
 public const POLICY='The normal weekly allocation is four teaching days and one Flexible Duties Day. Duties on this day are agreed or allocated by the centre manager according to operational priorities and may include teaching cover, marking, preparation, reviews, learner support and staff development. It is not a guaranteed non-teaching day.';
 public const OTHER_TYPES=['Marking','Preparation','Learner support','Staff development'];
 public static function event(User $u,string $event,string $type,string|int $id,int $version,array $data):void {DB::table('timetable_duty_events')->insert(['actor_id'=>$u->id,'event'=>$event,'subject_type'=>$type,'subject_key'=>(string)$id,'record_version'=>$version,'payload'=>Crypt::encryptString(json_encode($data,JSON_THROW_ON_ERROR)),'created_at'=>now()]);}
 public static function briefIntact(Brief $b):bool {try{$d=$b->details;return $d&&ReviewedImports::hash($d)===$b->details_hash&&$d['group_id']===$b->group_id&&$d['version']===$b->version&&$d['by']===$b->updated_by;}catch(\Throwable){return false;}}
 public static function facts(int $id):array {
  $g=TutorGroup::find($id);if(!$g){return ['known'=>false,'name'=>'Group source needs checking','count'=>null,'start'=>null,'start_label'=>'Unknown','notes'=>null,'programme'=>null,'brief_current'=>false];}$b=Brief::find($id);$valid=$b&&self::briefIntact($b);$first=Apprentice::where('tutor_group_id',$id)->whereNotNull('start_date')->min('start_date');$date=$valid?($b->details['start_date']??null):null;return ['known'=>true,'name'=>$g->name,'count'=>Apprentice::where('tutor_group_id',$id)->count(),'start'=>$date,'start_label'=>$date?'Recorded group start':'Group start not recorded','earliest_apprentice_start'=>$first?Carbon::parse($first)->toDateString():null,'notes'=>$valid?$b->details['notes']:null,'programme'=>$g->programme?->name,'brief_current'=>!$b||(bool)$valid];
 }
 public static function brief(User $actor,int $auth,TutorGroup $record,int $version,?string $start,string $notes):void {DB::transaction(function()use($actor,$auth,$record,$version,$start,$notes):void {$u=CentrePlanning::actor($actor,$auth);$g=TutorGroup::whereKey($record->id)->lockForUpdate()->firstOrFail();$b=Brief::whereKey($g->id)->lockForUpdate()->first();if(($b?->version??0)!==$version||mb_strlen($notes)>1000||preg_match('/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/u',$notes)){CentrePlanning::fail('Group brief changed or contains invalid shared text.');}if($start){try{$date=Carbon::createFromFormat('!Y-m-d',$start);}catch(\Throwable){CentrePlanning::fail('Use a valid recorded group start.');}if($date->toDateString()!==$start){CentrePlanning::fail('Use a real recorded group start.');}}$before=$b?->details;$b??=new Brief(['group_id'=>$g->id,'version'=>0]);$b->version++;$b->updated_by=$u->id;$b->details=['group_id'=>$g->id,'version'=>$b->version,'by'=>$u->id,'start_date'=>$start,'notes'=>trim($notes)];$b->details_hash=ReviewedImports::hash($b->details);$b->save();self::event($u,'group_brief','group',$g->id,$b->version,['before'=>$before,'after'=>$b->details]);},3);}
 public static function dayFields(Day $d):array {return ['id'=>$d->id,'staff_id'=>$d->staff_id,'date'=>$d->work_date->toDateString(),'start'=>$d->start_time,'end'=>$d->end_time,'owner_id'=>$d->owner_id,'state'=>$d->state,'version'=>$d->version];}
 public static function dayIntact(Day $d):bool {try{return $d->source&&ReviewedImports::hash($d->source)===$d->source_hash&&$d->source['fields']===self::dayFields($d);}catch(\Throwable){return false;}}
 public static function dayBasis(User $staff,User $owner,string $date,string $start,string $end,bool $lock=false):array {
  $u=User::whereKey($staff->id)->when($lock,fn($q)=>$q->lockForUpdate())->firstOrFail();$o=User::whereKey($owner->id)->when($lock,fn($q)=>$q->lockForUpdate())->firstOrFail();$w=Window::where('user_id',$u->id)->whereDate('work_date',$date)->when($lock,fn($q)=>$q->lockForUpdate())->first();if(!CentrePlanning::staff($u)||!CentrePlanning::hasRole($o)||!$w||!CentrePlanning::windowIntact($w)||!$w->working||$start<$w->start_time||$end>$w->end_time||CentrePlanning::minutes($end)-CentrePlanning::minutes($start)<5){CentrePlanning::fail('Flexible duties needs current staff, a current centre-planner owner and a checked working window covering the whole allocation.');}return ['staff'=>ReviewAppointments::seal($u),'owner'=>ReviewAppointments::seal($o),'window'=>CentrePlanning::windowProof($w),'timezone'=>config('app.timezone')];
 }
 public static function dayCurrent(Day $d):bool {try{return self::dayIntact($d)&&$d->state==='Active'&&$d->source['basis']===self::dayBasis(User::findOrFail($d->staff_id),User::findOrFail($d->owner_id),$d->work_date->toDateString(),$d->start_time,$d->end_time);}catch(\Throwable){return false;}}
 public static function day(int $staff,string $date):?Day {return Day::where('staff_id',$staff)->whereDate('work_date',$date)->first();}
 public static function preview(User $staff,array $dates):array {return ['staff'=>ReviewAppointments::seal(User::findOrFail($staff->id)),'windows'=>CentrePlanning::windowSource($staff,$dates),'days'=>Day::where('staff_id',$staff->id)->whereIn(DB::raw('DATE(work_date)'),$dates)->orderBy('work_date')->get()->map(fn($d)=>['fields'=>self::dayFields($d),'hash'=>$d->source_hash,'intact'=>self::dayIntact($d)])->all(),'dates'=>$dates];}
 public static function saveDays(User $actor,int $auth,User $staff,User $owner,array $dates,string $expected,string $start,string $end):void {DB::transaction(function()use($actor,$auth,$staff,$owner,$dates,$expected,$start,$end):void {User::whereIn('id',[$actor->id,$staff->id,$owner->id])->orderBy('id')->lockForUpdate()->get();$u=CentrePlanning::actor($actor,$auth);if(!$dates||count($dates)>26||count(array_unique($dates))!==count($dates)||ReviewedImports::hash(self::preview($staff,$dates))!==$expected){CentrePlanning::fail('Exact flexible-duty preview changed. Reload before replacing dated allocations.');}foreach($dates as$date){CentrePlanning::dates($date,1);if(!Carbon::parse($date.' '.$start,config('app.timezone'))->gt(now())){CentrePlanning::fail('Use future flexible-duty allocations.');}$basis=self::dayBasis($staff,$owner,$date,$start,$end,true);$d=self::day($staff->id,$date)??new Day(['staff_id'=>$staff->id,'work_date'=>$date,'version'=>0]);$before=$d->source;$d->owner_id=$owner->id;$d->start_time=$start;$d->end_time=$end;$d->state='Active';$d->version++;if(!$d->exists){$d->source=[];$d->source_hash=str_repeat('0',64);$d->save();}$d->source=['fields'=>self::dayFields($d),'basis'=>$basis,'policy'=>self::POLICY,'by'=>$u->id];$d->source_hash=ReviewedImports::hash($d->source);$d->save();self::event($u,'flexible_day_saved','day',$d->id,$d->version,['before'=>$before,'after'=>$d->source]);}},3);}
 public static function withdrawDay(User $actor,int $auth,Day $record,int $version):void {DB::transaction(function()use($actor,$auth,$record,$version):void {$u=CentrePlanning::actor($actor,$auth);$d=Day::whereKey($record->id)->lockForUpdate()->firstOrFail();if(!self::dayIntact($d)||$d->version!==$version||$d->state!=='Active'||!Carbon::parse($d->work_date->toDateString().' '.$d->start_time,config('app.timezone'))->gt(now())){CentrePlanning::fail('Withdraw only the current future flexible-duty classification.');}$before=$d->source;$d->state='Withdrawn';$d->version++;$s=$d->source;$s['fields']=self::dayFields($d);$s['withdrawn_by']=$u->id;$s['withdrawn_at']=now()->toIso8601String();$d->source=$s;$d->source_hash=ReviewedImports::hash($s);$d->save();self::event($u,'flexible_day_withdrawn','day',$d->id,$d->version,['before'=>$before,'after'=>$s,'booked_work_unchanged'=>true]);},3);}
 public static function gapParts(int $staff,string $date,int $a,int $b):array {$d=self::day($staff,$date);if(!$d||!self::dayCurrent($d)){return [[$a,$b,'Available']];}$x=CentrePlanning::minutes($d->start_time);$y=CentrePlanning::minutes($d->end_time);$out=[];if($a<min($b,$x)){$out[]=[$a,min($b,$x),'Available'];}if(max($a,$x)<min($b,$y)){$out[]=[max($a,$x),min($b,$y),'Flexible duties — unallocated'];}if(max($a,$y)<$b){$out[]=[max($a,$y),$b,'Available'];}return $out;}
 public static function pattern(int $staff,array $dates,array $rows):array {$flex=0;$teaching=0;$unknown=0;$other=0;foreach($dates as$date){$d=self::day($staff,$date);if($d&&self::dayCurrent($d)){$flex++;continue;}$w=Window::where('user_id',$staff)->whereDate('work_date',$date)->first();if(!$w||!CentrePlanning::windowIntact($w)){$unknown++;continue;}if(collect($rows)->contains(fn($r)=>$r['staff_id']===$staff&&$r['work_date']===$date&&$r['kind']==='Teaching')){$teaching++;}else{$other++;}}return ['ordinary_teaching_days'=>$teaching,'flexible_duties_days'=>$flex,'other_recorded_days'=>$other,'unknown_days'=>$unknown,'normal_pattern'=>4===$teaching&&1===$flex,'contractual_compliance_inferred'=>false];}

}
